"""Analyze actual complete C0/F2 batches and justified optional-candidate gate."""
from pathlib import Path
import json,argparse,hashlib

def closeout(root):
 root=Path(root);report={'status':'COMPLETE_CONDITIONAL_FINITE_MODEL','configurations':['C0','F2'],'complete_kernel_clock_qualified':False,'estimated_seconds_at_qualified_clock':None,'board_measured':False,'board_measured_seconds':None,'cases':{},'optional_candidate_run':False,'software_boundary':'RESIDENT_COMPLETE_BATCH_V2','memory_contract':{'latency_ns':80,'issue_interval_ns':5,'physical_ports':32,'beat_bytes':32,'credits_per_port':32,'assumed_frequency_hz':200000000}}
 for case,target in [('bnn_export',0.151799969444),('lstm_s2',0.15949799988888888)]:
  results={}
  for cfg in ['C0','F2']:
   summary=json.loads((root/f'{cfg}_{case}_summary.json').read_text());assert summary['all_pass']and summary['complete_batch'];fs=[json.loads(Path(r['finite_path']).read_text())for r in summary['sample_receipts']];assert len(fs)==40
   token_slot_cycles=sum(sum(sum(i*n for i,n in enumerate(g['occupancy_histograms'][0]))for g in x['group_stats'])for x in fs);pop=sum(x['pop_transactions']for x in fs);hist=[sum(c['exclusive_histogram'][k]for x in fs for c in x['critical_final_bank_observers'])for k in range(8)];ph=summary['phase_cycles'];cycles=summary['conditional_cycles']
   source_total=sum(sum(map(sum,x['traffic']))for x in fs);names=fs[0]['memory_kind_names'];traffic={name:sum(sum(x['traffic'][k])for x in fs)for k,name in enumerate(names)}
   observed=sum(sum(g['occupancy_histograms'][0])for x in fs for g in x['group_stats']);full=sum(g['occupancy_histograms'][0][128//x['groups']]for x in fs for g in x['group_stats'])
   results[cfg]={'conditional_cycles':cycles,'conditional_frequency_hz':200000000,'conditional_seconds':cycles/200000000,'phase_cycles':ph,'complete_output_sha256':summary['full_output_sha256'],'counts':summary['counts'],'request_counts':traffic,'request_total':source_total,'mean_token_lifetime_cycles':token_slot_cycles/pop,'token_slot_cycles':token_slot_cycles,'token_reservations':pop,'max_pop_transactions_per_sample':max(x['pop_transactions']for x in fs),'max_pop_transactions_below_2p24':all(x['pop_transactions']<2**24 for x in fs),'max_physical_line':max(x['cost_base_line']+x['cost_table_lines']-1 for x in fs),'max_physical_line_below_2p32':all(x['cost_base_line']+x['cost_table_lines']-1<2**32 for x in fs),'group_full_fraction_of_observed_group_cycles':full/observed,'critical_final_tail_exclusive_histogram':hist,'critical_final_labels':['retirement','publication','K8_full','scratch_merge','commit_input','enum','other_bank_tail','bitmap_drain'],'pendingK_peak':max(b['tx_peak']for x in fs for b in x['bank_stats']),'spill_peak':max(b['spill_id_peak']for x in fs for b in x['bank_stats']),'directory_peak_per_bank':max(max(x['directory_bank_peaks'])for x in fs),'ACK_peak_per_cycle':max(x['output_ACK_peak_per_cycle']for x in fs),'ACK_backpressure_source_cycles':sum(x['output_ACK_rejected_source_cycles']for x in fs),'zero_finalize_diagnostic_seconds':(cycles-ph['finalize'])/200000000,'zero_finalize_diagnostic_scope':'Subtracting a measured disjoint phase from this schedule is diagnostic, NOT a lower bound on another architecture or a simulated alternative.'}
  a,b=results['C0'],results['F2'];report['cases'][case]={'results':results,'F2_gain_over_C0_percent':(1-b['conditional_cycles']/a['conditional_cycles'])*100,'reused_GPU_resident_target_seconds':target,'F2_conditional_time_over_GPU_target':b['conditional_seconds']/target,'F2_below_GPU_target':b['conditional_seconds']<target,'zero_finalize_still_slower_than_GPU':b['zero_finalize_diagnostic_seconds']>target}
 reps=json.loads((root/'representatives_comparison.json').read_text())
 assert all(v['zero_finalize_still_slower_than_GPU'] for v in report['cases'].values()), 'New full evidence requires fresh supplementary-candidate assessment'
 assert all(rows['F3']['phase_cycles']['pop_expand']>=rows['C0']['phase_cycles']['pop_expand'] for rows in reps['cases'].values()), 'Interleave prerequisite must be reassessed'
 report['supplementary_gate']={'K16':'Not selected: actual final-tail observer publication-held states dominate this exclusive observer, with no positive evidence isolating K8 as the critical wait; full expansion already exceeds target in the measured schedule. No claimed K sensitivity without a finite one-variable implementation.','merge2':'Not selected: actual final-tail scratch/merge observations do not establish the required critical single-inflight dependency; even diagnostic removal of all finalize does not close the measured gap.','two_sample_interleave':'Not selected: F3 fusion does not reduce expansion in matched complete representatives, so the guidance prerequisite is absent. No max(old_expand,old_finalize) time substitution and no unimplemented double payload/URAM claim.','scope':'NO_GO_THIS_CONFIGURATION; does not rule out other FPGA structures. No alternate clock or memory service point is claimed; changed clocks/services require new model execution.'}
 (root/'full_analysis.json').write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({case:{'F2_seconds':v['results']['F2']['conditional_seconds'],'gain_percent':v['F2_gain_over_C0_percent'],'GPU_target':v['reused_GPU_resident_target_seconds']}for case,v in report['cases'].items()},indent=2));return report
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('root');closeout(p.parse_args().root)
